   113  //  Returns true, if file is a binary or ASCII Model 3D file.
   114  bool M3DImporter::CanRead(const std::string &pFile, IOSystem *pIOHandler, bool checkSig) const {
   115      const std::string extension = GetExtension(pFile);
   116
   117      if (extension == "m3d"
   118              || extension == "a3d"
   119      )
   120          return true;
   121      else if (!extension.length() || checkSig) {
   122          if (!pIOHandler) {
   123              return true;
   124          }
   125          /*
   126           * don't use CheckMagicToken because that checks with swapped bytes too, leading to false
   127           * positives. This magic is not uint32_t, but char[4], so memcmp is the best way
   128
   129          const char* tokens[] = {"3DMO", "3dmo"};
   130          return CheckMagicToken(pIOHandler,pFile,tokens,2,0,4);
   131          */
   132          std::unique_ptr<IOStream> pStream(pIOHandler->Open(pFile, "rb"));
   133          unsigned char data[4];
   134          if (!pStream || 4 != pStream->Read(data, 1, 4)) {
   135              return false;
   136          }
   137          return !memcmp(data, "3DMO", 4) /* bin */
   138                 || !memcmp(data, "3dmo", 4) /* ASCII */
   139                  ;
   140      }
   141      return false;
   142  }
