   151  void M3DImporter::InternReadFile(const std::string &file, aiScene *pScene, IOSystem *pIOHandler) {
   152      // Read file into memory
   153      std::unique_ptr<IOStream> pStream(pIOHandler->Open(file, "rb"));
   154      if (!pStream.get()) {
   155          throw DeadlyImportError("Failed to open file ", file, ".");
   156      }
   157
   158      // Get the file-size and validate it, throwing an exception when fails
   159      size_t fileSize = pStream->FileSize();
   160      if (fileSize < 8) {
   161          throw DeadlyImportError("M3D-file ", file, " is too small.");
   162      }
   163      std::vector<unsigned char> buffer(fileSize);
   164      if (fileSize != pStream->Read(buffer.data(), 1, fileSize)) {
   165          throw DeadlyImportError("Failed to read the file ", file, ".");
   166      }
   167      // extra check for binary format's first 8 bytes. Not done for the ASCII variant
   168      if (!memcmp(buffer.data(), "3DMO", 4) && memcmp(buffer.data() + 4, &fileSize, 4)) {
   169          throw DeadlyImportError("Bad binary header in file ", file, ".");
   170      }
   171      // make sure there's a terminator zero character, as input must be ASCIIZ
   172      if (!memcmp(buffer.data(), "3dmo", 4)) {
   173          buffer.push_back(0);
   174      }
   175
   176      // Get the path for external assets
   177      std::string folderName("./");
   178      std::string::size_type pos = file.find_last_of("\\/");
   179      if (pos != std::string::npos) {
   180          folderName = file.substr(0, pos);
